/*
 * SOURCE OF TRUTH: bench/harness/ready.js — edit that file, never a copy. The
 * three tracked bench/apps/<app>/gotth/bench/ copies are generated by
 * bench/scripts/sync-ready.mjs, asserted identical by verify-ready.sh (D-6).
 */
/*
 * The gotth-live side of equivalence-spec §3.3's `ready` signal.
 *
 * §3.3 fixes the condition per stack and the STAMP is taken by the shim on both,
 * so the number D5 publishes comes from the same code either way. What differs
 * is what has to have happened before `window.__bench.ready = true` is assigned:
 *
 *   gotth-live   live connection handshake complete (FR-8) AND the initial
 *                Snapshot/first patch applied AND the delegated event root
 *                attached (FR-28)
 *   Next.js      React hydration complete for the interactive region AND the
 *                live-data channel open AND its first message applied
 *
 * All three gotth-live conditions are satisfied at exactly one observable
 * moment, and this file waits for it rather than approximating it:
 *
 *   - The delegated event root is attached by the runtime's start(), before a
 *     socket is constructed. It is therefore in place strictly earlier than
 *     anything below.
 *   - `data-gotth-status="live"` is written on <html> by setStatus, and the
 *     Snapshot branch of the runtime's onMessage is the ONLY transition into
 *     "live" (client/runtime.js: `setStatus("live"); applied(f.snapshot);`).
 *     So the attribute reaching "live" means the handshake completed AND the
 *     protocol version was re-asserted in band AND a Snapshot frame arrived.
 *   - The two calls are consecutive statements in one task, and a
 *     MutationObserver callback is delivered at the microtask checkpoint after
 *     that task's stack empties. By the time this file's callback runs, the
 *     snapshot has been APPLIED and not merely received — which is the half of
 *     §3.3's condition an attribute alone would not have proved.
 *
 * Why this is a served .js file and not an inline <script>. §3.5 counts every
 * response with a JavaScript MIME type against the stack's client-JS payload.
 * Inlining these bytes into the document would move them out of D1 and into the
 * HTML figure, which is an accounting advantage gotth-live has not earned: the
 * Next.js side's equivalent lives inside its hydration bundle and is counted
 * there. It is served as text/javascript so D1 counts it, and bench/README.md
 * states the size.
 *
 * It is deliberately NOT part of harness/shim.js. The shim is one file,
 * byte-identical, served by both stacks (§2.0), and a per-stack branch inside
 * it is a review finding (§3).
 *
 * It also mirrors data-gotth-status onto data-bench-status. That is not a
 * second job: the one stylesheet each app serves is the Next.js side's file
 * byte for byte (§2.1's "one stylesheet", and E5's element bounds are stated
 * against one document), and that file selects the connection indicator on
 * data-bench-status because the attribute is written by the OTHER stack's
 * client component. Mirroring is what makes the same bytes light the same dot
 * on both sides; without it the two documents would differ in one visible
 * respect for no reason either stack chose.
 */
(function () {
  'use strict';

  var root = document.documentElement;
  var signalled = false;

  function sync() {
    var status = root.getAttribute('data-gotth-status');
    if (status === null) {
      return false;
    }
    if (root.getAttribute('data-bench-status') !== status) {
      root.setAttribute('data-bench-status', status);
    }
    if (signalled || status !== 'live') {
      return false;
    }
    signalled = true;
    if (window.__bench) {
      window.__bench.ready = true;
    }
    /* The observer stays attached after the signal: the indicator has to keep
       following the connection, and §3.3's "exactly once" is held by the flag
       above rather than by disconnecting. */
    return true;
  }

  /* The attribute may already say "live": this script is deferred and the
     runtime's own tag is deferred too, so their relative order is the document
     order of the tags and not something to depend on. */
  sync();

  new MutationObserver(sync).observe(root, {
    attributes: true,
    attributeFilter: ['data-gotth-status'],
  });
})();
